const expectedKey = String($env.N8N_AUTOMATION_KEY || '');
const validItems = [];
$input.all().forEach((item, index) => {
  const envelope = item.json || {};
  if (envelope.body) {
    const suppliedKey = String(envelope.headers?.['x-automation-key'] || envelope.headers?.['X-Automation-Key'] || '');
    if (!expectedKey || suppliedKey !== expectedKey) throw new Error('Unauthorized article webhook request');
  }
  const source = envelope.body || envelope.article || envelope;
  const articleId = String(source.articleId || source._id || '');
  if (!/^[a-f0-9]{24}$/i.test(articleId)) return;
  const title = String(source.title || '').trim();
  if (!title) return;
  let content = String(source.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (content.length < 100) {
    content = `${title}. ${String(source.subtitle || '')}. ${String(source.aiSummary || '')}. ${content}`.trim();
  }
  validItems.push({
    json: {
      articleId,
      title,
      subtitle: String(source.subtitle || ''),
      content,
      category: String(source.category || 'general'),
      tags: Array.isArray(source.tags) ? source.tags : [],
      slug: String(source.slug || ''),
      aiSummary: String(source.aiSummary || ''),
      publishedAt: source.publishedAt || source.createdAt || new Date().toISOString(),
      embeddingText: `${title}\n\n${String(source.subtitle || '')}\n\n${content.slice(0, 7000)}`
    },
    pairedItem: { item: index }
  });
});
return validItems;

const originals = $('Normalize Article').all();
return $input.all().map((item, index) => {
  const source = originals[index]?.json || originals[0]?.json;
  const vector = item.json.embedding?.values || item.json.embeddings?.[0]?.values || [];
  if (!Array.isArray(vector) || vector.length !== 768) throw new Error(`Expected a 768-dimensional embedding, received ${vector.length}`);
  const hex = source.articleId.toLowerCase();
  const pointId = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}00000000`;
  return { json: { ...source, vector, pointId }, pairedItem: { item: index } };
});

const preparedItems = $('Prepare Vector').all();
return $input.all().map((item, index) => {
  const source = preparedItems[index]?.json || preparedItems[0]?.json;
  const points = Array.isArray(item.json.result?.points) ? item.json.result.points : (Array.isArray(item.json.result) ? item.json.result : []);
  const duplicate = points.some((point) => Number(point.score || 0) > 0.92);
  const related = points
    .filter((point) => Number(point.score || 0) >= 0.75 && Number(point.score || 0) <= 0.92 && point.payload?.articleId)
    .slice(0, 3);
  const context = related.slice(0, 2).map((point, contextIndex) => {
    const payload = point.payload || {};
    return `Past article ${contextIndex + 1}: ${payload.title || ''}\n${payload.summary || ''}`;
  }).join('\n\n');
  const prompt = related.length
    ? `Current article: ${source.title}\n${source.aiSummary || source.subtitle || source.content.slice(0, 900)}\n\nVerified related archive:\n${context}\n\nWrite exactly two concise, factual sentences explaining the historical context. Use only the supplied material. Start with "The Backstory:". Do not invent dates, people, or events.`
    : '';
  return {
    json: {
      ...source,
      isDuplicateEcho: duplicate,
      relatedArticles: related.map((point) => String(point.payload.articleId)),
      backstoryPrompt: prompt,
      hasRelatedContext: related.length > 0
    },
    pairedItem: { item: index }
  };
});

const classifiedItems = $('Classify Similarity').all();
return $input.all().map((item, index) => {
  const source = classifiedItems[index]?.json || classifiedItems[0]?.json;
  const parts = item.json?.candidates?.[0]?.content?.parts || [];
  const generated = parts.map((part) => part.text || '').join(' ').trim();
  const backstory = source.hasRelatedContext && generated && generated.toLowerCase() !== 'empty string' ? generated.slice(0, 2000) : '';
  return { json: { ...source, backstory }, pairedItem: { item: index } };
});
